solution:
type Score = {
  points: Int;
  invariant: points >= 0;
}

fn add_points(score: &mut Score, pts: Int)
  requires: pts > 0;
  ensures: score.points == score@pre.points + pts;
{
  score.points = score.points + pts;
}

fn read_score(score: &Score) -> Int {
  return score.points;
}

fn main() -> Int {
  var s: Score = Score{ points: 0 };
  add_points(&mut s, 10);
  add_points(&mut s, 5);
  return read_score(&s);
}
